void twoSum(int* a,int n,int t,int* lo,int* hi){
    *lo=0; *hi=n-1;
    while(*lo<*hi){
        int s=a[*lo]+a[*hi];
        if(s==t) return;
        else if(s<t)(*lo)++; else(*hi)--;
    }
    *lo=*hi=-1;
}

